/**
 * checkCommitMessage — validates a commit message against the project's commit conventions.
 *
 * Why: commit history is part of the audit trail. Conventional Commits make it scannable, and a
 *      `Refs:` footer links each feature or fix to the requirements it serves.
 * Spec: DOC-011
 * Invariants:
 *   - Header: `type(scope)?: summary` with a known type and at most 100 characters.
 *   - `feat` and `fix` commits carry a `Refs:` footer; every ID listed there must exist.
 *   - Merge and revert commits generated by git are accepted unchanged.
 * Collaborators: .husky/commit-msg (runs it on every commit), ./lib/repo.mjs.
 * Tests: tools/doc-lint/test/commitMessage.test.mjs
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { knownRequirementIds } from './lib/repo.mjs';

/** Conventional Commit types accepted in this repository. */
export const TYPES = [
  'feat',
  'fix',
  'docs',
  'style',
  'refactor',
  'perf',
  'test',
  'build',
  'ci',
  'chore',
  'revert',
];
const HEADER = new RegExp(`^(${TYPES.join('|')})(\\([a-z0-9-]+\\))?!?: \\S.{0,98}$`);

/**
 * Checks one commit message.
 * @param {string} message - Full commit message (comment lines starting with # are ignored).
 * @param {Set<string>} ids - Known requirement IDs.
 * @returns {string[]} Problems; empty when the message is acceptable.
 */
export function checkCommitMessage(message, ids) {
  const lines = message.split('\n').filter((l) => !l.startsWith('#'));
  const header = lines[0] ?? '';
  if (/^(Merge|Revert) /.test(header)) return [];
  const problems = [];
  const match = HEADER.exec(header);
  // WHY: the regex caps only the summary; the whole header (type and scope included) has the 100-character limit.
  if (header.length > 100) problems.push(`header is ${header.length} characters; the limit is 100`);
  if (!match)
    problems.push(`header must look like "type(scope): summary" (types: ${TYPES.join(', ')}), max 100 chars`);
  const refsLine = lines.find((l) => /^Refs:/.test(l));
  if (match && ['feat', 'fix'].includes(match[1]) && !refsLine)
    problems.push('feat and fix commits need a "Refs:" footer');
  for (const ref of refsLine?.match(/\b[A-Z][A-Z0-9]*-\d{3}\b/g) ?? []) {
    if (!ids.has(ref)) problems.push(`Refs: names unknown requirement ${ref}`);
  }
  return problems;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const root = fileURLToPath(new URL('../../', import.meta.url));
  const problems = checkCommitMessage(readFileSync(process.argv[2], 'utf8'), knownRequirementIds(root));
  for (const p of problems) console.error(`✗ commit message: ${p}`);
  if (problems.length > 0) process.exit(1);
}
